package __PKG__;

import java.io.IOException;
import java.io.Reader;
import java.io.Writer;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.StandardCopyOption;
import java.util.Properties;

/** Simple persistent key/value storage (data.properties). Generated by Minecraft Builder. */
public final class Storage {
    private static final Properties DATA = new Properties();
    private static Path file;

    private Storage() {}

    public static synchronized void init(Path dir) {
        file = dir.resolve("data.properties");
        DATA.clear();
        try {
            Files.createDirectories(dir);
            if (Files.exists(file)) {
                try (Reader r = Files.newBufferedReader(file, StandardCharsets.UTF_8)) {
                    DATA.load(r);
                }
            }
        } catch (IOException e) {
            e.printStackTrace();
        }
    }

    private static void save() {
        if (file == null) return;
        try {
            Path tmp = file.resolveSibling("data.properties.tmp");
            try (Writer w = Files.newBufferedWriter(tmp, StandardCharsets.UTF_8)) {
                DATA.store(w, "Minecraft Builder data");
            }
            Files.move(tmp, file, StandardCopyOption.REPLACE_EXISTING);
        } catch (IOException e) {
            e.printStackTrace();
        }
    }

    public static synchronized double getNum(String key) {
        String v = DATA.getProperty(key);
        if (v == null) return 0;
        try {
            return Double.parseDouble(v);
        } catch (NumberFormatException e) {
            return 0;
        }
    }

    public static synchronized void setNum(String key, double value) {
        DATA.setProperty(key, Double.toString(value));
        save();
    }

    public static synchronized double addNum(String key, double by) {
        double n = getNum(key) + by;
        setNum(key, n);
        return n;
    }

    public static synchronized String getText(String key) {
        return DATA.getProperty("t." + key, "");
    }

    public static synchronized void setText(String key, String value) {
        DATA.setProperty("t." + key, value == null ? "" : value);
        save();
    }
}
